import{_ as a}from"./chunks/gem5-cache-hierarchy.BC_kpT6Z.js";import{_ as n,c as l,d as e,Z as p}from"./chunks/framework.B0uuYL3Y.js";const u=JSON.parse('{"title":"不同的数据为什么会在末级缓存里互相挤掉","description":"从多核共享范围算到同组替换，再看包含关系怎样改变核心实际发出的 LLC 请求。","frontmatter":{"title":"不同的数据为什么会在末级缓存里互相挤掉","description":"从多核共享范围算到同组替换，再看包含关系怎样改变核心实际发出的 LLC 请求。","date":"2026-11-25","tags":["微架构安全","共享资源","LLC","高速缓存"],"book":"microarch-00-intro"},"headers":[],"relativePath":"posts/microarch-06a-shared-cache.md","filePath":"posts/microarch-06a-shared-cache.md"}'),o={name:"posts/microarch-06a-shared-cache.md"};function t(r,s,c,i,d,y){return l(),e("div",null,s[0]||(s[0]=[p('<p>两个核心各读自己的数组，物理地址没有重叠。B 读完以后，A 的三条数据中，有两条已经被换出末级缓存（Last-Level Cache，LLC）。A 再次读取这三条数据，会有两次还是三次未命中？如果 A 的私有缓存里还有副本，答案又会怎样？</p><p>这两道题要沿同一条路径顺次判断。先看两个核心是否共用 LLC，再由地址算出它们是否竞争同一个组，最后检查核心重新加载时能从哪一级取得数据。先修知识是<a href="./microarch-01b-cache-mapping.html#cache-address">地址如何选组</a>和<a href="./microarch-01b-cache-mapping.html#cache-replacement">组内替换</a>。</p><nav class="table-of-contents"><ul><li><a href="#llc-domain">两条访问路径在哪一级汇合</a></li><li><a href="#llc-set">六个不同的块怎样争四路</a></li><li><a href="#llc-inclusion">LLC 换出一行，私有缓存会怎样</a><ul><li><a href="#用代码复算请求最后在哪一级取数">用代码复算请求最后在哪一级取数</a></li></ul></li><li><a href="#llc-evidence">从请求数和未命中数读出变化</a></li><li><a href="#参考文献">参考文献</a></li></ul></nav><h2 id="llc-domain" tabindex="-1">两条访问路径在哪一级汇合 <a class="header-anchor" href="#llc-domain" aria-label="Permalink to &quot;两条访问路径在哪一级汇合 {#llc-domain}&quot;">​</a></h2><p>图 1 是 gem5 课程给出的缓存层次示例。各核心先访问自己的 L1，走到互连之后才进入下方的末级缓存。图中画了两个 LLC 块。共享缓存可以有多块存储结构，实际请求按照系统的地址和路由规则被送往相应位置。图示用于说明共享接口所在的位置，后面的题目会直接指定共用一个 LLC 实例。</p><figure class="lesson-figure" style="max-width:550px;"><a href="/microarch/gem5-cache-hierarchy.png" aria-label="查看 gem5 缓存层次原图"><img src="'+a+`" alt="gem5 缓存层次中，多个核心先连接各自的 L1，再经互连接到 LLC" width="550" height="387" style="filter:grayscale(1);background-color:white;" loading="lazy" decoding="async"></a><figcaption>图 1　从各自的 L1 到可能共用的 LLC。上半部是核心侧，下半部经系统互连接向内存控制器。</figcaption></figure><p>题目比图中多设一级私有 L2。A、B 各有 L1 和 L2，二者的请求经过私有层后汇合到同一个共享 LLC。若 A 在私有 L2 找到了数据，正常的读访问已能返回。分析 LLC 替换时，先从完整访问序列中过滤出实际到了 LLC 的请求。</p><p>真实平台上要怎样确认这个汇合点？以 Linux 的缓存接口为例，从 <code>/sys/devices/system/cpu/</code> 进入选定的 <code>cpuN</code>，在其 <code>cache/indexK</code> 目录中读取 <code>level</code> 和 <code>type</code>，找出目标级别与类型。接着读 <code>id</code> 和 <code>shared_cpu_list</code>。<code>indexK</code> 是该 CPU 的缓存信息目录编号。缓存实例 ID 应在同一级别与类型下比较。下面是一组用于读配置的示意值。</p><table tabindex="0"><thead><tr><th>逻辑 CPU</th><th>目标级别和类型</th><th style="text-align:right;">实例 ID</th><th>可共用这个实例的 CPU</th></tr></thead><tbody><tr><td>0</td><td>L3，Unified</td><td style="text-align:right;">0</td><td>0–3</td></tr><tr><td>2</td><td>L3，Unified</td><td style="text-align:right;">0</td><td>0–3</td></tr><tr><td>4</td><td>L3，Unified</td><td style="text-align:right;">1</td><td>4–7</td></tr></tbody></table><p>A 在 CPU 0、B 在 CPU 2 时，可用同一个 LLC 实例解释两者的分配。若 B 移到 CPU 4，B 的新分配使用另一个实例。这个变化能解除两者对同一 LLC 组的争用，但共享的内存节点、互连等仍要另查。若真实处理器在一个 LLC 实例内还有多个分片，也要确认访问是否竞争相同分片上的组。下文使用单片的教学模型，避免让具体平台的路由规则混入例题。</p><h2 id="llc-set" tabindex="-1">六个不同的块怎样争四路 <a class="header-anchor" href="#llc-set" aria-label="Permalink to &quot;六个不同的块怎样争四路 {#llc-set}&quot;">​</a></h2><p>设模型的 LLC 有 4 组，每组 4 路，行长为 64 字节。地址均为题设中的物理地址，块号对 4 取余选组。选择同一个组才会争这一组的四个位置。分配时先用空路，组满后换掉最久未用的行，即精确 LRU。</p><table tabindex="0"><thead><tr><th>工作负载</th><th>块的名称</th><th>各块的首地址</th><th>组号</th></tr></thead><tbody><tr><td>A</td><td>A0、A1、A2</td><td><code>0x2000</code>、<code>0x2100</code>、<code>0x2200</code></td><td>均为 0</td></tr><tr><td>B</td><td>B0、B1、B2</td><td><code>0x2300</code>、<code>0x2400</code>、<code>0x2500</code></td><td>均为 0</td></tr></tbody></table><p>例如，<code>0x2200 / 64 = 0x88</code>，再对 4 取余得到 0。六条行的块号各不相同，组号却相同。整个 LLC 有 16 个行位置，其他组可以有空位，而这六个块在题设中只能使用组 0 的四路。后面只数实际到达这个 LLC 的读请求，并假定每次填充在下一次读之前完成。</p><p>A 先把 A0、A1、A2 读进 LLC。现在让 B 依次读 B0、B1、B2，然后 A 再按原顺序读一次。表中顺序从最久未用排到最近使用。</p><table tabindex="0"><thead><tr><th>请求</th><th>结果</th><th>被换出的块</th><th>组 0 的状态</th></tr></thead><tbody><tr><td>A 完成第一轮</td><td>三块已填入</td><td>无</td><td>A0、A1、A2</td></tr><tr><td>B0</td><td>未命中</td><td>无，有空路</td><td>A0、A1、A2、B0</td></tr><tr><td>B1</td><td>未命中</td><td>A0</td><td>A1、A2、B0、B1</td></tr><tr><td>B2</td><td>未命中</td><td>A1</td><td>A2、B0、B1、B2</td></tr><tr><td>A0</td><td>未命中</td><td>A2</td><td>B0、B1、B2、A0</td></tr><tr><td>A1</td><td>未命中</td><td>B0</td><td>B1、B2、A0、A1</td></tr><tr><td>A2</td><td>未命中</td><td>B1</td><td>B2、A0、A1、A2</td></tr></tbody></table><p>B 停止读取时，A2 仍在 LLC。A 先重读 A0 并把它填进 LLC，这一步又挤掉了 A2。于是 B 直接换出了 A 的两块，A 自己的后续填充使第三个块也未命中。用<a href="./microarch-01-cache.html#locality-reuse">复用距离</a>可以重算这一点。在 A2 的两次访问之间，组 0 先后用了 B0、B1、B2、A0、A1，已经超过了四路能保留的范围。</p><p>现在只改 B 的布局，将三个首地址都增加 <code>0x40</code>。每个块号加 1，B 就转到组 1。A 不用改动顺序，下一轮三个请求都可在组 0 命中。布局保持同组时，还可以用<a href="./microarch-06c-cat.html#cat-ways">CAT 的四路例题</a>重算限制填充位置后的结果。这里两个核心访问的是不同物理块。若两个字段实际落在同一物理块，且存在写入，则还需分析一致性和<a href="./microarch-01g-false-sharing.html#sharing-layout">伪共享</a>。</p><h2 id="llc-inclusion" tabindex="-1">LLC 换出一行，私有缓存会怎样 <a class="header-anchor" href="#llc-inclusion" aria-label="Permalink to &quot;LLC 换出一行，私有缓存会怎样 {#llc-inclusion}&quot;">​</a></h2><p>回到原布局，把此前略去的私有 L2 加回来。A 第一轮结束后，假定三条干净的数据同时在私有 L2 和 LLC，L1 的细节省略。随后 A 暂停，B 仍然读 B0、B1、B2。这时要看内存层次有没有以下约束。</p><ul><li><strong>包含式 LLC。</strong> 私有层保留的块必须在 LLC 里也有对应缓存块。为维持这个关系，LLC 换出 A0 时，要让私有层相关副本先失效。目录或一致性机制负责找到这些副本。</li><li><strong>非包含式 LLC。</strong> 私有缓存可以持有当前未驻留在 LLC 的块。如果实现允许保留，B 换出 LLC 的 A0 后，A 的 L2 仍可命中。更改共享状态或写入相同块时仍需遵守一致性规则。</li></ul><table tabindex="0"><thead><tr><th>阶段</th><th>保持包含关系</th><th>允许私有层继续保留干净副本</th></tr></thead><tbody><tr><td>B 读完三块</td><td>LLC 去掉 A0、A1，A 的 L2 也失去这两块</td><td>LLC 去掉 A0、A1，A 的 L2 保留三块</td></tr><tr><td>A 再读 A0</td><td>L2 未命中，LLC 未命中。填充 A0 换出 A2，使其 L2 副本失效</td><td>在 L2 命中</td></tr><tr><td>A 继续读 A1、A2</td><td>两笔都到 LLC，均未命中</td><td>两笔均在 L2 命中</td></tr><tr><td>A 第二轮到达 LLC 的次数</td><td>3</td><td>0</td></tr></tbody></table><p>表里右列是针对干净只读副本的教学条件。真实非包含式处理器还可能有独立的目录资源和其他替换约束。Intel 对第一代 Xeon Scalable 的技术说明明确指出，在它的非包含式 LLC 中，某块不在 LLC 无法据此判断它也不在私有缓存。读测量结果时，需要分别核实私有层命中、LLC 请求和下级流量。</p><h3 id="用代码复算请求最后在哪一级取数" tabindex="-1">用代码复算请求最后在哪一级取数 <a class="header-anchor" href="#用代码复算请求最后在哪一级取数" aria-label="Permalink to &quot;用代码复算请求最后在哪一级取数&quot;">​</a></h3><p>下列 Python 3 模型实现组内 LRU 和上述两层关系。<code>keep_private</code> 为假时，A 第一轮结束后直接把私有层设为空，复算前面的 LLC 组表。它为真时，保留 A 第一轮取得的三条行。<code>inclusive</code> 决定 LLC 换出时是否移除私有副本。例子用 <code>下级</code> 表示这次查找还要交给 LLC 以下的服务层。</p><div class="language-python line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#93A1A1;font-weight:bold;">def</span><span style="color:#268BD2;"> replay</span><span style="color:#839496;">(a_blocks, b_blocks, </span><span style="color:#859900;">*</span><span style="color:#839496;">, keep_private, inclusive):</span></span>
<span class="line"><span style="color:#839496;">    private </span><span style="color:#859900;">=</span><span style="color:#839496;"> {</span><span style="color:#2AA198;">&quot;A&quot;</span><span style="color:#839496;">: </span><span style="color:#859900;">set</span><span style="color:#839496;">(), </span><span style="color:#2AA198;">&quot;B&quot;</span><span style="color:#839496;">: </span><span style="color:#859900;">set</span><span style="color:#839496;">()}</span></span>
<span class="line"><span style="color:#839496;">    llc </span><span style="color:#859900;">=</span><span style="color:#839496;"> [[] </span><span style="color:#859900;">for</span><span style="color:#839496;"> _ </span><span style="color:#859900;">in</span><span style="color:#268BD2;"> range</span><span style="color:#839496;">(</span><span style="color:#D33682;">4</span><span style="color:#839496;">)]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">    def</span><span style="color:#268BD2;"> read</span><span style="color:#839496;">(core, address):</span></span>
<span class="line"><span style="color:#839496;">        block </span><span style="color:#859900;">=</span><span style="color:#839496;"> address </span><span style="color:#859900;">//</span><span style="color:#D33682;"> 64</span></span>
<span class="line"><span style="color:#859900;">        if</span><span style="color:#839496;"> block </span><span style="color:#859900;">in</span><span style="color:#839496;"> private[core]:</span></span>
<span class="line"><span style="color:#859900;">            return</span><span style="color:#2AA198;"> &quot;L2&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#839496;">        group </span><span style="color:#859900;">=</span><span style="color:#839496;"> llc[block </span><span style="color:#859900;">%</span><span style="color:#268BD2;"> len</span><span style="color:#839496;">(llc)]</span></span>
<span class="line"><span style="color:#859900;">        if</span><span style="color:#839496;"> block </span><span style="color:#859900;">in</span><span style="color:#839496;"> group:</span></span>
<span class="line"><span style="color:#839496;">            group.remove(block)</span></span>
<span class="line"><span style="color:#839496;">            source </span><span style="color:#859900;">=</span><span style="color:#2AA198;"> &quot;LLC&quot;</span></span>
<span class="line"><span style="color:#859900;">        else</span><span style="color:#839496;">:</span></span>
<span class="line"><span style="color:#839496;">            source </span><span style="color:#859900;">=</span><span style="color:#2AA198;"> &quot;下级&quot;</span></span>
<span class="line"><span style="color:#859900;">            if</span><span style="color:#268BD2;"> len</span><span style="color:#839496;">(group) </span><span style="color:#859900;">==</span><span style="color:#D33682;"> 4</span><span style="color:#839496;">:</span></span>
<span class="line"><span style="color:#839496;">                victim </span><span style="color:#859900;">=</span><span style="color:#839496;"> group.pop(</span><span style="color:#D33682;">0</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#859900;">                if</span><span style="color:#839496;"> inclusive:</span></span>
<span class="line"><span style="color:#859900;">                    for</span><span style="color:#839496;"> copies </span><span style="color:#859900;">in</span><span style="color:#839496;"> private.values():</span></span>
<span class="line"><span style="color:#839496;">                        copies.discard(victim)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#839496;">        group.append(block)</span></span>
<span class="line"><span style="color:#839496;">        private[core].add(block)</span></span>
<span class="line"><span style="color:#859900;">        return</span><span style="color:#839496;"> source</span></span>
<span class="line"></span>
<span class="line"><span style="color:#859900;">    for</span><span style="color:#839496;"> address </span><span style="color:#859900;">in</span><span style="color:#839496;"> a_blocks:</span></span>
<span class="line"><span style="color:#839496;">        read(</span><span style="color:#2AA198;">&quot;A&quot;</span><span style="color:#839496;">, address)</span></span>
<span class="line"><span style="color:#859900;">    if</span><span style="color:#859900;"> not</span><span style="color:#839496;"> keep_private:</span></span>
<span class="line"><span style="color:#839496;">        private[</span><span style="color:#2AA198;">&quot;A&quot;</span><span style="color:#839496;">].clear()</span></span>
<span class="line"><span style="color:#859900;">    for</span><span style="color:#839496;"> address </span><span style="color:#859900;">in</span><span style="color:#839496;"> b_blocks:</span></span>
<span class="line"><span style="color:#839496;">        read(</span><span style="color:#2AA198;">&quot;B&quot;</span><span style="color:#839496;">, address)</span></span>
<span class="line"><span style="color:#859900;">    return</span><span style="color:#839496;"> [read(</span><span style="color:#2AA198;">&quot;A&quot;</span><span style="color:#839496;">, address) </span><span style="color:#859900;">for</span><span style="color:#839496;"> address </span><span style="color:#859900;">in</span><span style="color:#839496;"> a_blocks]</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#839496;">a </span><span style="color:#859900;">=</span><span style="color:#839496;"> (</span><span style="color:#93A1A1;font-weight:bold;">0x</span><span style="color:#D33682;">2000</span><span style="color:#839496;">, </span><span style="color:#93A1A1;font-weight:bold;">0x</span><span style="color:#D33682;">2100</span><span style="color:#839496;">, </span><span style="color:#93A1A1;font-weight:bold;">0x</span><span style="color:#D33682;">2200</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">b </span><span style="color:#859900;">=</span><span style="color:#839496;"> (</span><span style="color:#93A1A1;font-weight:bold;">0x</span><span style="color:#D33682;">2300</span><span style="color:#839496;">, </span><span style="color:#93A1A1;font-weight:bold;">0x</span><span style="color:#D33682;">2400</span><span style="color:#839496;">, </span><span style="color:#93A1A1;font-weight:bold;">0x</span><span style="color:#D33682;">2500</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">separate_set </span><span style="color:#859900;">=</span><span style="color:#859900;"> tuple</span><span style="color:#839496;">(address </span><span style="color:#859900;">+</span><span style="color:#93A1A1;font-weight:bold;"> 0x</span><span style="color:#D33682;">40</span><span style="color:#859900;"> for</span><span style="color:#839496;"> address </span><span style="color:#859900;">in</span><span style="color:#839496;"> b)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#859900;">assert</span><span style="color:#839496;"> replay(a, b, keep_private</span><span style="color:#859900;">=</span><span style="color:#B58900;">False</span><span style="color:#839496;">, inclusive</span><span style="color:#859900;">=</span><span style="color:#B58900;">False</span><span style="color:#839496;">) </span><span style="color:#859900;">==</span><span style="color:#839496;"> [</span><span style="color:#2AA198;">&quot;下级&quot;</span><span style="color:#839496;">] </span><span style="color:#859900;">*</span><span style="color:#D33682;"> 3</span></span>
<span class="line"><span style="color:#859900;">assert</span><span style="color:#839496;"> replay(a, separate_set, keep_private</span><span style="color:#859900;">=</span><span style="color:#B58900;">False</span><span style="color:#839496;">, inclusive</span><span style="color:#859900;">=</span><span style="color:#B58900;">False</span><span style="color:#839496;">) </span><span style="color:#859900;">==</span><span style="color:#839496;"> [</span><span style="color:#2AA198;">&quot;LLC&quot;</span><span style="color:#839496;">] </span><span style="color:#859900;">*</span><span style="color:#D33682;"> 3</span></span>
<span class="line"><span style="color:#859900;">for</span><span style="color:#839496;"> inclusive </span><span style="color:#859900;">in</span><span style="color:#839496;"> (</span><span style="color:#B58900;">True</span><span style="color:#839496;">, </span><span style="color:#B58900;">False</span><span style="color:#839496;">):</span></span>
<span class="line"><span style="color:#839496;">    sources </span><span style="color:#859900;">=</span><span style="color:#839496;"> replay(a, b, keep_private</span><span style="color:#859900;">=</span><span style="color:#B58900;">True</span><span style="color:#839496;">, inclusive</span><span style="color:#859900;">=</span><span style="color:#839496;">inclusive)</span></span>
<span class="line"><span style="color:#859900;">    assert</span><span style="color:#839496;"> sources </span><span style="color:#859900;">==</span><span style="color:#839496;"> ([</span><span style="color:#2AA198;">&quot;下级&quot;</span><span style="color:#839496;">] </span><span style="color:#859900;">*</span><span style="color:#D33682;"> 3</span><span style="color:#859900;"> if</span><span style="color:#839496;"> inclusive </span><span style="color:#859900;">else</span><span style="color:#839496;"> [</span><span style="color:#2AA198;">&quot;L2&quot;</span><span style="color:#839496;">] </span><span style="color:#859900;">*</span><span style="color:#D33682;"> 3</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#268BD2;">    print</span><span style="color:#839496;">(inclusive, sources)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br></div></div><p><code>read</code> 先查私有层。私有命中会直接返回，LLC 的顺序也不会因此改变。只有访问到达 LLC 时，<code>group</code> 才会查找或换出。模型保留了观察顺序所需的状态，私有层容量足以容纳本例的块，且没有预取或其他请求。</p><h2 id="llc-evidence" tabindex="-1">从请求数和未命中数读出变化 <a class="header-anchor" href="#llc-evidence" aria-label="Permalink to &quot;从请求数和未命中数读出变化 {#llc-evidence}&quot;">​</a></h2><p>复查真实程序时，先固定工作量和执行位置，再比较各级事件。假如 A 单独运行和混合运行都执行了同样的加载，但到达 LLC 的请求数不同，应先看私有层的命中和副本状态。若到达 LLC 的请求数相同，混合运行的 LLC 未命中更多，则可沿同组替换的解释继续查。若未命中数也相同，仍可能是这些请求去了<a href="./microarch-06b-memory-queue.html#memory-controller">共用的内存控制器</a>，等了更久。各类硬件计数的实际定义和范围可对照<a href="./microarch-04a-measurement.html#pmu-path">用计时和计数器分析访存</a>。</p><details class="details custom-block"><summary>练习：B 反复读同一个块</summary><p>仍在 A 已经读过 A0、A1、A2 后运行 B。保持 B 的请求和 A 落在同一组，把 B 的序列改成只反复读取 B0。若 A 的下一轮全部到达 LLC，会有几次未命中？</p><p>零次。B0 第一次填进空路。再次读取 B0 可以在已有副本命中，无须为新块另找位置。把这个序列代入 <code>b_blocks</code>，模型会报告 A 的三次请求都命中 LLC。</p><p>再把条件改成包含式 LLC，且 A 的私有副本一开始都在，B 只各读一次 B0、B1。B1 换出 A0 后，A1、A2 都还在私有层。A 重新填入 A0 时换出 A1，重新填入 A1 时又换出 A2。因此 B 直接换出一块，A 最终仍出现三次 LLC 未命中。</p></details><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li><a href="https://gem5bootcamp.github.io/gem5-bootcamp-env/assets/slides/using-gem5-04-gem5-caches-tutorial.pdf#page=14" target="_blank" rel="noreferrer">Marjan Fariborz，gem5 Bootcamp《Cache Systems》第 14 页</a> · <a href="https://github.com/gem5bootcamp/gem5-bootcamp-env/blob/51590ae00b0e451c9b6a8854addbb94128ab4cac/LICENSE" target="_blank" rel="noreferrer">CC BY 4.0 许可</a> · 本文复用已裁出的图并以灰度显示。</li><li><a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel-xeon-processor-scalable-family-technical-overview.html" target="_blank" rel="noreferrer">Intel 第一代 Xeon Scalable 技术综述，缓存层次与数据放置</a></li><li><a href="https://pages.cs.wisc.edu/~markhill/papers/primer2020_2nd_edition.pdf" target="_blank" rel="noreferrer">Sorin、Hill、Wood，缓存一致性教材，包含式 LLC 与失效请求</a></li><li><a href="https://docs.kernel.org/6.12/arch/x86/resctrl.html#cache-ids" target="_blank" rel="noreferrer">Linux v6.12 resctrl 文档中的缓存实例 ID</a></li><li><a href="https://github.com/torvalds/linux/blob/v6.12/Documentation/ABI/testing/sysfs-devices-system-cpu" target="_blank" rel="noreferrer">Linux 内核的缓存 sysfs 接口定义</a></li></ul><nav class="article-nav" aria-label="系列文章导航"><p><a href="./microarch-04b-observation.html" class="article-nav-card article-nav-prev" rel="prev"><span class="article-nav-text"><small>上一篇</small><strong>时间差何时算作侧信道证据</strong></span></a></p><p><a href="./microarch-06b-memory-queue.html" class="article-nav-card article-nav-next" rel="next"><span class="article-nav-text"><small>下一篇</small><strong>未命中次数相同，为什么内存等待更长</strong></span></a></p></nav>`,33)]))}const m=n(o,[["render",t]]);export{u as __pageData,m as default};
